new_openai_error = '    let response = futures::executor::block_on(client.chat().create(request)).map_err(|_| {\n        planner_interpretation_unavailable_error(\n            "planner_request_failed",\n            "remote planner request failed",\n            true,\n            Some(serde_json::json!({\n                "provider": "OpenAI",\n                "model": profile.model,\n                "base_url": endpoint_scope.normalized_base_url(),\n            })),\n        )\n    })?;\n'
old_ollama_error = '    let response = futures::executor::block_on(client.chat().create(request)).map_err(|error| {\n        planner_interpretation_unavailable_error(\n            "planner_request_failed",\n            format!("Ollama planner request failed: {error}"),\n            true,\n            Some(serde_json::json!({\n                "provider": "Ollama",\n                "model": profile.model,\n                "base_url": profile.base_url,\n            })),\n        )\n    })?;\n'
new_ollama_error = '    let response = futures::executor::block_on(client.chat().create(request)).map_err(|_| {\n        planner_interpretation_unavailable_error(\n            "planner_request_failed",\n            "Ollama planner request failed",\n            true,\n            Some(serde_json::json!({\n                "provider": "Ollama",\n                "model": profile.model,\n                "base_url": endpoint_scope.normalized_base_url(),\n            })),\n        )\n    })?;\n'

